impl LohenDamageEnum {
    pub fn get_element(&self, in_masterstroke: bool) -> Element {
        use LohenDamageEnum::*;
        match *self {
            // 非奇谋状态下普攻/重击/下落为物理，奇谋状态下转为冰元素
            A1 | A2 | A3 | A3T | A4 | A51 | A52 | Z | ZT | X1 | X2 | X3 => {
                if in_masterstroke { Element::Cryo } else { Element::Physical }
            }
            // 奇谋状态下强化普攻/重击始终为冰元素
            E1 | E2 | E3 | E3T | E4 | E51 | E52 | EZ | EZT | EG | EGT | Q | QT | C2A | C2Z => Element::Cryo,
        }
    }

    pub fn get_skill_type(&self) -> SkillType {
        use LohenDamageEnum::*;
        match *self {
            A1 | A2 | A3 | A3T | A4 | A51 | A52 => SkillType::NormalAttack,
            Z | ZT => SkillType::ChargedAttack,
            X1 => SkillType::PlungingAttackInAction,
            X2 | X3 => SkillType::PlungingAttackOnGround,
            E1 | E2 | E3 | E3T | E4 | E51 | E52 => SkillType::NormalAttack,
            EZ | EZT => SkillType::ChargedAttack,
            EG | EGT => SkillType::ElementalSkill,
            Q | QT => SkillType::ElementalBurst,
            C2A => SkillType::NormalAttack,
            C2Z => SkillType::ChargedAttack,
        }
    }
}

