    fn change_attribute<A: Attribute>(attribute: &mut A, common_data: &CharacterCommonData, skill_config: &CharacterSkillConfig) {
        let (hexerei_secret_rite, avg_will_to_win) = match &common_data.config {
            CharacterConfig::Lohen { hexerei_secret_rite, avg_will_to_win } => (*hexerei_secret_rite, *avg_will_to_win),
            _ => (false, 0.0),
        };

        let (in_masterstroke, activated_cryo_reaction, evilsbane_blade) = match *skill_config {
            CharacterSkillConfig::Lohen { in_masterstroke, activated_cryo_reaction, evilsbane_blade } =>
                (in_masterstroke, activated_cryo_reaction, evilsbane_blade),
            _ => (false, false, false),
        };

        // P2: 戏言的杰作 —— 奇谋状态下触发冰元素相关反应后8秒内，触发者与洛恩攻击力+15%
        if common_data.has_talent2 && in_masterstroke && activated_cryo_reaction {
            attribute.set_value_by_t(
                AttributeType::Panel(AttributeName::ATKPercentage),
                "洛恩天赋2",
                0.15,
            );
        }

        // P3: 魔女的前夜礼·不愈之刺 —— 魔导秘仪：争胜≥50%时 NA/CA 增伤40%
        // 通过 avg_will_to_win 判断：未解锁C1时上限100，解锁C1时乘以5倍（上限300）
        let will_max = if common_data.constellation >= 1 { 300.0 } else { 100.0 };
        let effective_will = if common_data.constellation >= 1 {
            (avg_will_to_win * 5.0).min(will_max)
        } else {
            avg_will_to_win.min(will_max)
        };
        if hexerei_secret_rite && effective_will >= will_max * 0.5 {
            attribute.set_value_by_t(
                AttributeType::Invisible(InvisibleAttributeType::new_skill(AttributeVariableType::Bonus, SkillType::NormalAttack)),
                "洛恩天赋3",
                0.4,
            );
            attribute.set_value_by_t(
                AttributeType::Invisible(InvisibleAttributeType::new_skill(AttributeVariableType::Bonus, SkillType::ChargedAttack)),
                "洛恩天赋3",
                0.4,
            );
        }

        // C2: 破邪之刃 —— 触发后附近角色元素精通+200
        if common_data.constellation >= 2 && evilsbane_blade {
            attribute.set_value_by_s(
                CharacterSelector::select_all_except_self(attribute),
                AttributeType::Panel(AttributeName::ElementalMastery),
                "洛恩命座2",
                200.0,
            );
        }
    }

    fn damage_internal<D: DamageBuilder>(context: &DamageContext<'_, D::AttributeType>, s: usize, config: &CharacterSkillConfig, fumo: Option<Element>) -> D::Result {
        let s: LohenDamageEnum = num::FromPrimitive::from_usize(s).unwrap();
        let (s1, s2, s3) = context.character_common_data.get_3_skill();

        let (hexerei_secret_rite, avg_will_to_win) = match &context.character_common_data.config {
            CharacterConfig::Lohen { hexerei_secret_rite, avg_will_to_win } => (*hexerei_secret_rite, *avg_will_to_win),
            _ => (false, 0.0),
        };

        let (in_masterstroke, activated_cryo_reaction, evilsbane_blade) = match *config {
            CharacterSkillConfig::Lohen { in_masterstroke, activated_cryo_reaction, evilsbane_blade } =>
                (in_masterstroke, activated_cryo_reaction, evilsbane_blade),
            _ => (false, false, false),
        };

        // 计算有效争胜层数：
        // C1: 争胜上限变为300%，积累速度变为500%
        // 用户输入 avg_will_to_win 为应用一命效果前的平均层数
        // C4: 奇谋状态下施放Q时争胜积攒至上限
        let effective_will = if (s == Q || s == QT) && context.character_common_data.constellation >= 4 {
            // C4: Q时争胜填满至上限
            if context.character_common_data.constellation >= 1 { 300.0 } else { 100.0 }
        } else if context.character_common_data.constellation >= 1 {
            (avg_will_to_win * 5.0).min(300.0)
        } else {
            avg_will_to_win.min(100.0)
        };

        // C1 仅在奇谋状态下生效
        let will_bonus = if in_masterstroke {
            effective_will * LOHEN_SKILL.will_bonus
        } else {
            0.0
        };

        use LohenDamageEnum::*;
        let mut builder = D::new();

        // 需要奇谋状态才能触发的伤害
        if (s == E1 || s == E2 || s == E3 || s == E3T || s == E4 || s == E51 || s == E52 || s == EZ || s == EZT || s == EG || s == EGT) && !in_masterstroke {
            return builder.none();
        }

        // 需要命座才能触发的伤害
        if (s == C2A || s == C2Z) && context.character_common_data.constellation < 2 {
            return builder.none();
        }

        let ratio = match s {
            A1 => LOHEN_SKILL.a_dmg1[s1],
            A2 => LOHEN_SKILL.a_dmg2[s1],
            A3 => LOHEN_SKILL.a_dmg3[s1],
            A3T => LOHEN_SKILL.a_dmg3[s1] * 3.0,
            A4 => LOHEN_SKILL.a_dmg4[s1],
            A51 => LOHEN_SKILL.a_dmg51[s1],
            A52 => LOHEN_SKILL.a_dmg52[s1],
            Z => LOHEN_SKILL.z_dmg[s1],
            ZT => LOHEN_SKILL.z_dmg[s1] * 2.0,
            X1 => LOHEN_SKILL.x_dmg1[s1],
            X2 => LOHEN_SKILL.x_dmg2[s1],
            X3 => LOHEN_SKILL.x_dmg3[s1],
            E1 => LOHEN_SKILL.e_dmg1[s2],
            E2 => LOHEN_SKILL.e_dmg2[s2],
            E3 => LOHEN_SKILL.e_dmg3[s2],
            E3T => LOHEN_SKILL.e_dmg3[s2] * 3.0,
            E4 => LOHEN_SKILL.e_dmg4[s2],
            E51 => LOHEN_SKILL.e_dmg51[s2],
            E52 => LOHEN_SKILL.e_dmg52[s2],
            EZ => LOHEN_SKILL.e_z_dmg[s2],
            EZT => LOHEN_SKILL.e_z_dmg[s2] * 2.0,
            EG => LOHEN_SKILL.eg_dmg[s2],
            EGT => LOHEN_SKILL.eg_dmg[s2] * 4.0,
            Q => LOHEN_SKILL.q_dmg[s3],
            QT => LOHEN_SKILL.q_dmg[s3] * 6.0,
            C2A | C2Z => LOHEN_SKILL.c2_dmg,
        };

        // 镂骨彻心与元素爆发享受争胜加成
        let will_extra_ratio = match s {
            EG | EGT | Q | QT => will_bonus * ratio,
            _ => 0.0,
        };

        builder.add_atk_ratio("技能倍率", ratio);
        if will_extra_ratio > 0.0 {
            builder.add_atk_ratio("争胜加成", will_extra_ratio);
        }

        // C6: 暴击伤害+175%
        if context.character_common_data.constellation >= 6 {
            match s {
                EG | EGT | Q | QT => {
                    builder.add_extra_critical_damage("洛恩命座6", 1.75);
                }
                _ => {}
            }
        }

        builder.damage(
            &context.attribute,
            &context.enemy,
            s.get_element(in_masterstroke),
            s.get_skill_type(),
            context.character_common_data.level,
            fumo,
        )
    }

    fn new_effect<A: Attribute>(common_data: &CharacterCommonData, config: &CharacterConfig) -> Option<Box<dyn ChangeAttribute<A>>> {
        let (hexerei_secret_rite, avg_will_to_win) = match *config {
            CharacterConfig::Lohen { hexerei_secret_rite, avg_will_to_win } => (hexerei_secret_rite, avg_will_to_win),
            _ => (false, 0.0),
        };
        Some(Box::new(LohenEffect {
            hexerei_secret_rite,
            avg_will_to_win,
            common_data: common_data.clone(),
        }))
    }

